    public function getQueryBuilderBySearchData($searchData)
    {
        $qb = $this->createQueryBuilder('r');

        $qb->where('r.visible = true');

        // Staff
        if ( isset($searchData['Staff']) && StringUtil::isNotBlank($searchData['Staff']) ) {
            $qb
                ->andWhere("r.Staff = :staff")
                ->setParameter('staff', $searchData['Staff']);
        }
        // Customer
        if ( isset($searchData['Customer']) ) {
            $qb
                ->andWhere("r.Customer = :customer")
                ->setParameter('customer', $searchData['Customer']);
        }
        // working_ym
        if ( isset($searchData['working_ym']) ) {
            $qb
                ->andWhere("r.working_day >= :working_ym_s")
                ->setParameter('working_ym_s', $searchData['working_ym']->format('Y-m-d'));

            $searchData['working_ym'] = $searchData['working_ym'];
            $searchData['working_ym']->modify('+1 month');

            $qb
                ->andWhere("r.working_day < :working_ym_e")
                ->setParameter('working_ym_e', $searchData['working_ym']->format('Y-m-d'));
        }

        if ( isset($searchData['sortkey']) && $searchData['sortkey'] == 'customer_id' ) {
            $sortType = ( isset($searchData['sorttype']) && $searchData['sorttype'] == 'a' ) ? 'ASC' : 'DESC';
            $qb
                ->orderBy('r.Customer', $sortType)
                ->addOrderBy('r.working_day', 'DESC')
                ;
        }else{
            $qb
                ->orderBy('r.working_day', 'DESC');
        }

//echo $qb->getQuery()->getSQL();

        //return $this->queries->customize(QueryKey::REPORT_SEARCH, $qb, $searchData);
        return $this->queries->customize($this->getQueryKey(), $qb, $searchData);
    }

    /*
     * 請求暑発行
     * invoice_issued に存在しない
     * report に存在する
     */
     public function getQueryBuilderByIssueList($searchData)
     {
         $qb = $this->createQueryBuilder('r');

         $qb->leftJoin('Customize\Entity\InvoiceIssued', 'ii', 'WITH', 'ii.Customer = r.Customer')
             ->where('ii.Customer IS NULL');

         if ( isset($searchData['working_ym']) ) {
             $working_ym_s = date('Y-m-d', strtotime('first day of ' . $searchData['working_ym']));
             $working_ym_e = date('Y-m-d', strtotime('last day of ' . $searchData['working_ym']));
             $qb
                 ->andWhere("r.working_day >= :working_ym_s")
                 ->andWhere("r.working_day <= :working_ym_e")
                 ->setParameter('working_ym_s', $working_ym_s)
                 ->setParameter('working_ym_e', $working_ym_e);
         }

         $qb->groupBy('r.Customer');
         $qb->orderBy('r.Customer');

//         echo $qb->getQuery()->getSQL();
//         exit;

         return $this->queries->customize($this->getQueryKey(), $qb, $searchData);
     }

