    /*
     *
     */
    public function getQueryBuilderForPaySlipBySearchData($searchData)
    {
        $qb = $this->createQueryBuilder('r');

        $qb
            ->select('IDENTITY(r.Staff) as staff_id, count(r.Staff) as cnt')
            ->addSelect('CONCAT(s.name01, \' \', s.name02) as staff_name')
            ->innerJoin('Customize\Entity\Staff', 's', 'WITH', 's.id = r.Staff')
            ;

        $qb->where('r.visible = true');

        // Staff
        if ( isset($searchData['Staff']) && StringUtil::isNotBlank($searchData['Staff']) ) {
            $qb
                ->andWhere("r.Staff = :staff")
                ->setParameter('staff', $searchData['Staff']);
        }
        // Customer
        if ( isset($searchData['Customer']) ) {
            $qb
                ->andWhere("r.Customer = :customer")
                ->setParameter('customer', $searchData['Customer']);
        }
        // working_ym
        if ( isset($searchData['working_ym']) ) {
            $qb
                ->andWhere("r.working_day >= :working_ym_s")
                ->setParameter('working_ym_s', $searchData['working_ym']->format('Y-m-d'));

            $searchData['working_ym'] = $searchData['working_ym'];
            $searchData['working_ym']->modify('+1 month');

            $qb
                ->andWhere("r.working_day < :working_ym_e")
                ->setParameter('working_ym_e', $searchData['working_ym']->format('Y-m-d'));
        }

        $qb->groupBy('r.Staff');

        //return $this->queries->customize(QueryKey::REPORT_SEARCH, $qb, $searchData);
        return $this->queries->customize($this->getQueryKey(), $qb, $searchData);
    }

    /*
     *
     */
    public function getQueryBuilderForInvoiceBySearchData($searchData)
    {
        $qb = $this->createQueryBuilder('r');

        $qb
            ->select('IDENTITY(r.Customer) as customer_id, count(r.Customer) as cnt')
            ->addSelect('CONCAT(c.name01, \' \', c.name02) as customer_name')
            ->innerJoin('Eccube\Entity\Customer', 'c', 'WITH', 'c.id = r.Customer')
            ;

        $qb->where('r.visible = true');

        // Customer
        if ( isset($searchData['Staff']) && StringUtil::isNotBlank($searchData['Staff']) ) {
            $qb
                ->andWhere("r.Staff = :staff")
                ->setParameter('staff', $searchData['Staff']);
        }
        // Customer
        if ( isset($searchData['Customer']) && StringUtil::isNotBlank($searchData['Customer']) ) {
            $qb
                ->andWhere("r.Customer = :customer")
                ->setParameter('customer', $searchData['Customer']);
        }
        // working_ym
        if ( isset($searchData['working_ym']) ) {
            $working_ym_s = date('Y-m-d', strtotime('first day of ' . $searchData['working_ym']));
            $working_ym_e = date('Y-m-d', strtotime('last day of ' . $searchData['working_ym']));
            $qb
                ->andWhere("r.working_day >= :working_ym_s")
                ->setParameter('working_ym_s', $working_ym_s);

            $qb
                ->andWhere("r.working_day <= :working_ym_e")
                ->setParameter('working_ym_e', $working_ym_e);
        }
        // issue_status
        if ( isset($searchData['issue_status']) ) {
            if ( $searchData['issue_status'] == 'NULL' ) {
                $qb
                    ->andWhere("r.issue_status IS NULL");
            }else{
                $qb
                    ->andWhere("r.issue_status = :issue_status")
                    ->setParameter('issue_status', $searchData['issue_status']);
            }
        }
        $qb->groupBy('r.Customer');

        return $this->queries->customize($this->getQueryKey(), $qb, $searchData);
    }

    /*
     *
     */
    public function getMonthlyReportByStaff($searchData)
    {

        $qb = $this->createQueryBuilder('r');
        $qb->where('r.visible = true');

        // Staff
        if ( isset($searchData['Staff']) && StringUtil::isNotBlank($searchData['Staff']) ) {
            $qb
                ->andWhere("r.Staff = :staff")
                ->setParameter('staff', $searchData['Staff']);
        }
        // working_ym
        if ( isset($searchData['working_ym']) ) {
            $qb
                ->andWhere("r.working_day >= :working_ym_s")
                ->setParameter('working_ym_s', date('Y-m-d', strtotime('first day of ' . $searchData['working_ym'])));
            $qb
                ->andWhere("r.working_day < :working_ym_e")
                ->setParameter('working_ym_e', date('Y-m-d', strtotime('last day of ' . $searchData['working_ym'])) );
        }

        $qb->orderBy('r.working_day', 'ASC');


        return $qb->getQuery()->getResult();
    }

