    /*
     *
     */
    public function setIssueMonthlyReportByCustomer($searchData){

        $this->createQueryBuilder('r')
                ->update()
                ->set('r.issue_status', 1)
                ->where("r.Customer = :customer")
                ->andWhere("r.working_day >= :working_ym_s")
                ->andWhere("r.working_day < :working_ym_e")
                ->setParameter('customer', $searchData['Customer'])
                ->setParameter('working_ym_s', date('Y-m-d', strtotime('first day of ' . $searchData['working_ym'])))
                ->setParameter('working_ym_e', date('Y-m-d', strtotime('last day of ' . $searchData['working_ym'])))
                ->getQuery()
                ->execute();

        return;
    }

    /**
     * Get query key
     *
     * @return string
     */
    public function getQueryKey()
    {
        return 'Report.getQueryBuilderBySearchData';
    }

